apiRouter.post(
  "/admin/sync-snapshot",
  requireAdmin,
  upload.fields([
    { name: "db", maxCount: 1 },
    { name: "files", maxCount: 100 }
  ]),
  async (req, res) => {
    try {
      const filesMap = req.files;
      if (!filesMap) {
        return res.status(400).json({ error: "No files provided for snapshot sync" });
      }
      const dbFiles = filesMap["db"];
      const contentFiles = filesMap["files"] || [];
      if (dbFiles && dbFiles.length > 0) {
        const dbFile = dbFiles[0];
        const dbTarget = process.env.DB_PATH || path3.resolve(process.cwd(), "data", "ewaste.sqlite");
        const targetDir = path3.dirname(dbTarget);
        if (!fs3.existsSync(targetDir)) fs3.mkdirSync(targetDir, { recursive: true });
        await fs3.promises.writeFile(dbTarget, dbFile.buffer);
        await db.reload();
      }
      let filesWritten = 0;
      for (const f of contentFiles) {
        const internalId = path3.basename(f.originalname);
        await storageAdapter.save(f.buffer, internalId, internalId);
        filesWritten++;
      }
      const assignments = db.queryAll(
        "SELECT id, (SELECT COUNT(*) FROM assignment_files af WHERE af.assignment_id = assignments.id) as cnt FROM assignments"
      );
      const filesCount = db.queryOne("SELECT COUNT(*) as cnt FROM files");
      const sectionsWithFiles = assignments.filter((a) => a.cnt > 0).length;
      res.json({
        success: true,
        message: "Production snapshot sync completed successfully",
        filesWritten,
        databaseStats: {
          totalSections: assignments.length,
          sectionsWithFiles,
          totalFiles: filesCount?.cnt || 0
        }
      });
    } catch (err) {
      console.error("[EWEM Server] Error syncing snapshot:", err);
      res.status(500).json({ error: err.message });
    }
  }
);
